//! Server bindings: one module per protocol XML, generated by wayland-scanner.
//!
//! Each module holds that protocol's interface modules (`quire_window_v1::quire_window_v1`,
//! ...), as wayland-protocols lays its own out. An enum another protocol owns is named through
//! that protocol's interface module, which the generating module imports.

/// Generates one protocol's server module with the interfaces it builds on in scope.
macro_rules! server_protocol {
    ($(#[$doc:meta])* $name:ident, $path:literal, [$($imports:path),*]) => {
        $(#[$doc])*
        pub mod $name {
            #![allow(dead_code, non_camel_case_types, unused_unsafe, unused_variables)]
            #![allow(non_upper_case_globals, non_snake_case, unused_imports)]
            #![allow(missing_docs, missing_debug_implementations, clippy::all)]

            use wayland_server;
            use wayland_server::protocol::*;
            $(use $imports::{*};)*

            /// The protocol's interface descriptions.
            pub mod __interfaces {
                use wayland_server::protocol::__interfaces::*;
                $(use $imports::{__interfaces::*};)*
                wayland_scanner::generate_interfaces!($path);
            }
            use self::__interfaces::*;

            wayland_scanner::generate_server_code!($path);
        }
    };
}

server_protocol!(
    /// `quire-window-v1.xml`: what an app says about its toplevel.
    quire_window_v1,
    "protocols/quire-window-v1.xml",
    [wayland_protocols::xdg::shell::server]
);

server_protocol!(
    /// `quire-sensitive-v1.xml`: surfaces and regions kept from agents and capture.
    quire_sensitive_v1,
    "protocols/quire-sensitive-v1.xml",
    []
);

server_protocol!(
    /// `quire-agent-v1.xml`: agent leases.
    quire_agent_v1,
    "protocols/quire-agent-v1.xml",
    [
        wayland_protocols::ext::foreign_toplevel_list::v1::server,
        wayland_protocols::ext::image_capture_source::v1::server
    ]
);

server_protocol!(
    /// `quire-trusted-surface-v1.xml`: surfaces only the person can answer.
    quire_trusted_surface_v1,
    "protocols/quire-trusted-surface-v1.xml",
    []
);

server_protocol!(
    /// `quire-desktop-v1.xml`: the compositor's model of apps, windows and Spaces.
    quire_desktop_v1,
    "protocols/quire-desktop-v1.xml",
    [
        wayland_protocols::ext::foreign_toplevel_list::v1::server,
        crate::server::quire_window_v1,
        crate::server::quire_sensitive_v1,
        crate::server::quire_agent_v1
    ]
);

server_protocol!(
    /// `quire-shell-v1.xml`: the shell's surface roles and system events.
    quire_shell_v1,
    "protocols/quire-shell-v1.xml",
    [crate::server::quire_desktop_v1]
);
